import * as React from 'react';
import {AnimatePresence} from 'motion/react';
import {Film,SlidersHorizontal,Cpu,RotateCcw,Layers} from 'lucide-react';
import * as UI from './components/nbrain';
export default function WindowLab(){const bounds=React.useRef<HTMLDivElement>(null);const [order,setOrder]=React.useState(['preview','inspector','agents']);const [hidden,setHidden]=React.useState<string[]>([]);const [quality,setQuality]=React.useState('4k');const [exposure,setExposure]=React.useState(58);const [selected,setSelected]=React.useState(1);const [approved,setApproved]=React.useState(false);const focus=(id:string)=>setOrder(a=>a[a.length-1]===id?a:[...a.filter(i=>i!==id),id]);const hide=(id:string)=>setHidden(a=>a.includes(id)?a:[...a,id]);const restore=(id:string)=>{setHidden(a=>a.filter(i=>i!==id));focus(id)};const props=(id:string)=>({id,boundsRef:bounds,active:order[order.length-1]===id,zIndex:order.indexOf(id)+1,onFocus:()=>focus(id),onMinimize:()=>hide(id),onClose:()=>hide(id)});return <div className="window-lab"><div className="window-lab-toolbar"><div className="row"><span className="window-lab-indicator"/><span className="eyebrow">FLOATING PRODUCTION DESK</span></div><UI.Button size="sm" variant="ghost" onClick={()=>{setHidden([]);setOrder(['preview','inspector','agents'])}}><RotateCcw size={13}/>Restore windows</UI.Button></div><UI.WindowCanvas canvasRef={bounds}><div className="window-canvas-etch" aria-hidden="true"><UI.Wordmark/><span>STUDIO A / MODULAR WORKSPACE</span></div><AnimatePresence>{!hidden.includes('preview')&&<UI.FloatingWindow {...props('preview')} title="Sequence preview" subtitle="NIGHT DRIVE / V03" initialPosition={{x:30,y:80}} width={390} height={390}><UI.ShotCard number={selected} title="City arrival" selected onClick={()=>setSelected(n=>n===3?1:n+1)}/><div className="row between"><UI.Badge tone="blue">SCENE 04</UI.Badge><span className="mono small muted">4K / 24 FPS</span></div><div className="row"><UI.Button size="sm" variant="silver" onClick={()=>setApproved(!approved)}>{approved?'Approved':'Review cut'}</UI.Button><span className="small muted">Human decision</span></div></UI.FloatingWindow>}{!hidden.includes('inspector')&&<UI.FloatingWindow {...props('inspector')} title="Render inspector" subtitle="LOCAL PIPELINE" initialPosition={{x:460,y:40}} width={290} height={430}><UI.Field label="Delivery quality"><UI.Select value={quality} onValueChange={setQuality} label="Floating quality" options={[{value:'1080',label:'1080p / review'},{value:'4k',label:'4K / master'},{value:'8k',label:'8K / final'}]}/></UI.Field><UI.Slider label="Exposure" value={exposure} onValueChange={setExposure}/><UI.ResourceMeter label="Local GPU" value={72} total="22 / 32 GB · RTX 5090"/><UI.ConnectionStatus/><UI.Button variant="silver" size="sm" onClick={()=>setApproved(true)}>Apply settings</UI.Button></UI.FloatingWindow>}{!hidden.includes('agents')&&<UI.FloatingWindow {...props('agents')} title="Agent intelligence" subtitle="N CORE / LIVE" initialPosition={{x:245,y:310}} width={355} height={310}><div className="window-core-row"><UI.AgentCore size="sm"/><div><strong>Hermes production team</strong><p className="muted small">Three minds. One coordinated run.</p></div></div><UI.AgentCard agent={{id:'visuals',name:'Visuals',task:'Frame generation · local GPU',status:'running',progress:68}}/><UI.AgentCard agent={{id:'writing',name:'Writing',task:'Script locked',status:'ready'}}/><UI.Progress value={68}/></UI.FloatingWindow>}</AnimatePresence></UI.WindowCanvas><div className="window-dock" role="toolbar" aria-label="Window dock">{[{id:'preview',label:'Preview',icon:Film},{id:'inspector',label:'Inspector',icon:SlidersHorizontal},{id:'agents',label:'Agents',icon:Cpu}].map(item=><UI.Button key={item.id} size="sm" variant={hidden.includes(item.id)?'ghost':order[order.length-1]===item.id?'primary':'secondary'} onClick={()=>restore(item.id)} aria-pressed={!hidden.includes(item.id)&&order[order.length-1]===item.id}><item.icon size={14}/>{item.label}{hidden.includes(item.id)&&<span className="dock-minimized-dot"/>}</UI.Button>)}<span className="small muted">Drag titles · Resize corners · Double-click to maximize</span></div></div>}
